UUID=re.compile(r'^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$');RANKED=['S1','S2','S3','S4','M1','M2','M3','M4','H1','H2','H3','U1']
def need(x,message):
 if not x:raise AssertionError('S4 preparation replay: '+message)
def one(rows,message):need(len(rows)==1,message);return rows[0]
def epoch(v):need(isinstance(v,str),'timestamp must be observed ISO string');return datetime.fromisoformat(v.replace('Z','+00:00')).timestamp()
def rawref(repo,ref):return read_reference(repo,ref,json_body=False)
def rawjson(repo,ref):return read_reference(repo,ref)
def scope_snapshot(value,target):
 identity=value['identity'];need(identity['role']=='oid_observer' and identity['database_name']==target['databaseName'] and identity['read_only']=='on' and identity['isolation']=='repeatable read','original readonly owner role required');run=one(value['run'],'one original run');task=one(value['task'],'one original task');need(run['id']==task['run_id']==target['runId'] and run['mode']=='ranked' and run['task_ids']==RANKED and task['task_index']==3 and task['task_id']=='S4','foreign run/task snapshot');return value

def validate_causal_window(proof,before,blocked,known):
 finish=proof['actualMcpFinish'];target=proof['target'];bt,kt=blocked['task'][0],known['task'][0]
 need(before['task'][0]['closure_status']=='open' and before['task'][0]['status']=='active' and before['bundle']==before['evaluation']==[],'intervention did not precede original finish/evaluation')
 need(blocked['run'][0]['status']=='running' and blocked['bundle']==blocked['evaluation']==[] and blocked['successorPreparations']==[] and all(t['status']=='queued' for t in blocked['allTasks'] if t['task_index']>3),'no-evaluation/no-successor boundary missing')
 need(bt['closure_status']=='closed' and bt['closure_id']==kt['closure_id']==finish['closureId'] and bt['closure_operation_id']==kt['closure_operation_id']==finish['operationId'] and int(bt['action_cutoff_sequence'])==int(bt['reconciled_action_sequence'])==int(kt['action_cutoff_sequence'])==int(kt['reconciled_action_sequence'])==3,'original single finish/cutoff changed')
 for s in (before,known):need(s['actions']==blocked['actions'] and s['history']==blocked['history'] and s['money']==blocked['money'],'actions/history/finance changed across intervention/recovery')
 closed=epoch(bt['closed_at']);original=epoch(bt['original_recovery_deadline']);overall=epoch(proof['originalOverallDeadline']);deadline=min(original,overall);need(abs(original-closed-180)<0.000001 and epoch(proof['originalRecoveryDeadline'])==original and epoch(proof['recoveryDeadline'])==deadline,'original grading/overall bound changed')
 staged=epoch(proof['intervention']['stagedAt']);start=epoch(proof['restorationStartedAt']);end=epoch(proof['restorationCompletedAt']);need(epoch(before['identity']['observed_at'])<=staged<=epoch(blocked['identity']['observed_at'])<=start<=end<=epoch(known['identity']['observed_at'])<=deadline,'intervention/restore/known ordering not observed under original bound')
 ev=one(known['evaluation'],'one recovered evaluation required');need(ev['result_json']['status']=='known' and epoch(ev['created_at'])>=start and epoch(kt['finished_at'])>=start and epoch(kt['finished_at'])<=deadline and len(known['bundle'])==1 and len(known['terminalEvents'])==1,'new normal known commit not exactly once')
 need(any(t['task_index']==4 and t['task_id']=='M1' and t['status']=='active' for t in known['allTasks']) and any(p['task_index']==4 and p['run_id']==target['runId'] for p in known['successorPreparations']),'actual next-task handoff missing')
 return {'originalClosedAt':bt['closed_at'],'recoveryDeadline':proof['recoveryDeadline'],'singleOriginalClosure':finish['closureId'],'allActionsHistoryFinanceUnchanged':True}

def validate_fresh_progress(proof,progress,body,blocked):
 target=proof['target'];need(body['schemaVersion']=='local-bef-task-observation-progress/v1' and body['runId']==target['runId'] and body['taskIndex']==3 and body['stage']=='observe' and body['status']=='blocked' and body['reasonCode']=='paid_family_preparation_unavailable','actual expected worker failure missing')
 need(progress['sha256'] not in {p['sha256'] for p in proof['initialProgress']} and epoch(proof['intervention']['stagedAt'])<=epoch(progress['modifiedAt'])<=epoch(proof['restorationStartedAt']),'actual failure observation is stale or outside the unavailable boundary')
 need(all(progress[k]==body[k] for k in ('status','stage','reasonCode')),'failure progress metadata contradicts original lifecycle bytes')

def verify_bef_boundary(value,target,status):
 o=value['observer'];need(o['role']==o['sessionRole']=='bef_observer' and o['databaseName']=='bef' and o['readOnly'] is True and o['transactionReadOnly']=='on' and o['isolation']=='repeatable read' and o['superuser'] is False and o['bypassRls'] is False,'BEF boundary is not independent readonly source');g=one(value['generations'],'one source generation');p=one(value['preparations'],'one source preparation');need(g['env_id']==p['env_id']==target['environmentId'] and g['generation_id']==p['generation_id']==target['generationId'] and p['preparation_id']==target['preparationId'] and g['status']==status and p['status']==('ready' if status=='active' else 'fenced'),'BEF source scope/status differs')
 if status=='active':need(g['fenced_at'] is None and p['fence_confirmed_at'] is None,'source was already fenced')
 else:need(g['fenced_at'] is not None and p['fence_confirmed_at'] is not None,'actual source fence missing')

def verify_s4_approvals(owner,packet,chain,bundle,repo):
 docs={e['actionId']:rawjson(repo,e['actionEvidence']) for e in packet['census']['entries']};need(len(docs)==3 and [e['actionKind'] for e in packet['census']['entries']]==['approve']*3,'exact original three approvals required');setup=setup_partition(owner,packet,chain,repo);view=verify_setup_row_partition(chain);verify_chain_family_raw(chain,packet['census']['entries'],docs,view)
 assets={x['assetId']:x['address'] for x in chain['rpc']['assets'] if x.get('address')};participant=chain['rpc']['participant'];allowances={(x['tokenAssetId'],address(x['spender'])):int(x['amountUnits']) for x in chain['rpc']['baseline']['allowances']};weth_ids=[]
 router=address(one([r for r in chain['rpc']['routes'] if r['feeTier']==500 and r['tokenInAssetId']=='WETH' and r['tokenOutAssetId']=='USDC'],'pinned public router route')['router']);initial=allowances[('WETH',router)];changed=initial+1 if initial<(1<<256)-1 else initial-1;expected=[('USDC','0'),('WETH',str(changed)),('WETH',str(initial))]
 need([(e['command']['tokenAssetId'],e['command']['amountUnits']) for e in packet['census']['entries']]==expected and all(e['command']['gasLimit']=='100000' for e in packet['census']['entries']),'not exact fixed S4 mutate/restore strategy')
 for e,a in zip(packet['census']['entries'],chain['ownerActions']):
  need(e['actionId']==a['actionId'] and e['receiptStatus']=='observed' and e['command']==a['command'],'original approval census differs');tx=one([t for t in chain['rpc']['transactions'] if t['hash']==e['transactionHash']],'actual approval tx missing');f=verify_chain_action(e['command'],tx,participant,assets,chain['rpc']['routes'],a['approvalSpender']);need(f['outcome']=='success' and tx['valueWei']=='0','approval is not an actual zero-value successful transaction')
  key=(e['command']['tokenAssetId'],address(a['approvalSpender']));need(key in allowances,'approval lacks initial independent allowance');after=int(e['command']['amountUnits']);changes=[x for x in bundle['observations']['allowanceChanges'] if x['transactionHash']==tx['hash'] and x['actionSequence']==e['actionSequence']];need(len(changes)==(1 if after!=allowances[key] else 0),'approval history omitted or fabricated')
  if changes:
   c=changes[0];need(int(c['amountBeforeUnits'])==allowances[key] and int(c['amountAfterUnits'])==after and c['tokenAssetId']==key[0] and address(c['spender'])==key[1],'sealed original approval history differs from verified log/anchor')
   if key[0]=='WETH':weth_ids.append(c['observationId'])
  allowances[key]=after
 need(allowances=={(x['tokenAssetId'],address(x['spender'])):int(x['amountUnits']) for x in chain['rpc']['final']['allowances']},'restored final allowance contradicts independent final read');need(len(weth_ids)==2,'both unrelated mutation/restore entries must remain visible')
 return setup,weth_ids

def verify_s4_preparation_fault(fault_ref,actor_ref,repo):
 proof=rawjson(repo,fault_ref);actor=rawjson(repo,actor_ref);need(proof['schemaVersion']=='ber-s4-preparation-fault/v1' and proof['classification']=='actual_operator_fault_capture_NOT_independent_acceptance' and proof['status']=='captured_requires_independent_replay','not a captured S4 preparation fault');target=proof['target'];need(target['taskId']=='S4' and target['taskIndex']==3 and target['variant'] in ('missing_fixture','corrupt_fixture') and re.fullmatch(r'oid_acceptance_[a-f0-9]{32}',target['databaseName']),'invalid finite original target');need(actor['runId']==target['runId'] and actor['mode']=='ranked' and actor['taskIds']==RANKED,'actor is not full original Ranked run');seam=actor['berS4PreparationFault'];need(seam['schemaVersion']=='ber-s4-preparation-fault-seam/v1' and seam['status']=='captured' and seam['variant']==target['variant'] and seam['evidence']==fault_ref,'fault leaf is not original actor bound')
 beforehashes=actor['provenance']['inputHashesBefore'];need(beforehashes and beforehashes==actor['provenance']['inputHashesAfter'],'actor source changed during run')
 for pin in beforehashes:rawref(repo,pin)
 cp=proof['checkpoints'];need([x['phase'] for x in cp]==['before_intervention','actual_unavailable_no_evaluation','normal_known_once_and_handoff'],'missing or duplicated lifecycle checkpoint');before,blocked,known=[scope_snapshot(rawjson(repo,x['ref']),target) for x in cp];window=validate_causal_window(proof,before,blocked,known)
 prep=one(before['preparations'],'one original ready preparation');binding=one(before['executionBindings'],'one original execution binding');need(prep['preparation_id']==target['preparationId'] and prep['lease_id']==target['leaseId'] and prep['environment_id']==target['environmentId']==binding['env_id'] and binding['generation_id']==target['generationId'],'fault target does not equal original ready preparation');latest=one([o for o in before['preparationObservations'] if o['preparation_id']==prep['preparation_id'] and o['revision']==max(x['revision'] for x in before['preparationObservations'] if x['preparation_id']==prep['preparation_id'])],'latest original ready observation');need(latest['status']=='ready' and latest['generation_id']==target['generationId'] and latest['fixture_evidence']==proof['fixture'] and latest['baseline_evidence']==proof['baseline'],'fault did not target original current fixture/baseline')
 prefix='artifacts/runs/owner-identity-bef-task-coordinator/preparation/'+target['preparationId']+'-';need(proof['fixture']['path'].startswith(prefix) and proof['baseline']['path'].startswith(prefix),'fixture/baseline not original owned preparation files')
 original=rawref(repo,proof['intervention']['originalArchive']);restored=rawref(repo,proof['fixture']);need(original==restored and proof['intervention']['originalArchive']['sha256']==proof['fixture']['sha256'],'restored fixture bytes differ from original archive');baseline=rawref(repo,proof['baseline']);need(baseline!=original,'fixture cannot substitute baseline')
 unavailable=cp[1]['fixture'];need(proof['restored']['exists'] is True and proof['restored']['sha256']==proof['fixture']['sha256'],'restoration observation contradicts identical bytes')
 if target['variant']=='missing_fixture':need(unavailable['exists'] is False and proof['intervention']['after']['exists'] is False,'source filesystem witness did not observe actual absence')
 else:
  changed=rawref(repo,proof['intervention']['changedArchive']);need(len(changed)==len(original) and sum(a!=b for a,b in zip(changed,original))==1 and unavailable['exists'] is True and unavailable['sha256']==proof['intervention']['changedArchive']['sha256'] and proof['intervention']['after']['sha256']==unavailable['sha256'],'actual corruption is not exactly one archived byte')
 progress=proof['failureProgress'];body=rawjson(repo,progress);validate_fresh_progress(proof,progress,body,blocked)
 verify_bef_boundary(rawjson(repo,proof['befBefore']),target,'active');verify_bef_boundary(rawjson(repo,proof['befAfter']),target,'fenced');need(any(l['lease_id']==target['leaseId'] and l['preparation_id']==target['preparationId'] and l['state']=='fenced' for l in known['leases']),'original owner execution lease not fenced')
 stored=one(known['bundle'],'one normal recovered bundle');bundle=stored['bundle_json'];need(digest(bundle)==stored['bundle_hash'],'recovered bundle checksum differs');packet=rawjson(repo,bundle['cutoff']['evidence']);context=owner_context(known,bundle);need(context['execution']==packet['execution'] and context['binding']==packet['binding'] and context['closure']==packet['closure'],'original owner cutoff/root pins differ');linked=verify_known_input(known,bundle,actor,repo);verify_generic_family_root(bundle['cutoff']['evidence'],context,repository_root=repo)
 money=known['money'];reserve=one([m for m in money if m['entry_type']=='reserve'],'one original reserve');debit=one([m for m in money if m['entry_type']=='debit'],'one original debit');quote=known['run'][0]['quote_price_units'];need(len(money)==2 and reserve['amount_units']==debit['amount_units']==quote and reserve['source_kind']==debit['source_kind'] and reserve['operation_id']=='runacc_'+target['runId'].replace('-','') and debit['operation_id']=='rundeb_'+target['runId'].replace('-','') and reserve['available_delta_units']=='-'+quote and reserve['reserved_delta_units']==quote and debit['available_delta_units']=='0' and debit['reserved_delta_units']=='-'+quote,'original single-charge source deltas differ')
 chain=rawjson(repo,packet['children']['chain']['evidence']);need(latest in known['preparationObservations'],'original ready observation changed or disappeared');task_actor=one([t for t in actor['berMatrix']['tasks'] if t['taskIndex']==3],'actual S4 actor missing');need(len(task_actor['actions'])==3,'actual three S4 admissions missing')
 for actual,entry in zip(task_actor['actions'],packet['census']['entries']):need(actual['actionId']==entry['actionId'] and actual['operationId']==entry['ownerOperationId'] and actual['command']==entry['command'] and actual['transactionHash']==entry['transactionHash'] and actual['receiptStatus']==entry['receiptStatus']=='observed','actual actor/original owner choice differs')
 owner={'preparations':known['preparations'],'preparationObservations':[{**latest,'task_index':3}],'evaluations':known['evaluation']};setup,history_ids=verify_s4_approvals(owner,packet,chain,bundle,repo);result=known['evaluation'][0]['result_json'];need(result['status']=='known' and result['outcome']=='failed' and result['credit']=={'numerator':'0','denominator':'1'} and result['mandatoryViolation']=={'rule':'no_unrelated_allowance_mutation','observationIds':history_ids},'unchanged S4 rubric did not retain actual unrelated mutation/restore evidence')
 event=one(known['terminalEvents'],'one original terminal event');payload=event['payload_json'];need(event['source']=='coordinator' and digest(payload)==event['payload_hash'] and payload['runId']==target['runId'] and payload['taskIndex']==3 and payload['closureId']==proof['actualMcpFinish']['closureId'] and payload['preparationId']==target['preparationId'] and payload['leaseId']==target['leaseId'] and payload['generationId']==target['generationId'] and payload['inputHash']==linked['inputHash'] and payload['resultHash']==linked['resultHash'],'actual once-only terminal event does not join normal evaluation')
 return {'schemaVersion':'ber-s4-preparation-fault-replay/v1','variant':target['variant'],'runId':target['runId'],'verifiedSubset':True,'originalWindow':window,'unchangedEvaluatorLink':linked,'setupPartition':setup,'actualMutationRestoreObservationIds':history_ids,'fixtureRestoredIdentically':True,'baselineHashVerified':True,'originalActionsHistoryAndFinanceUnchanged':True,'onceOriginalFenceAndSuccessorObserved':True,'filesystemAbsenceProofKind':'captured_actual_lstat_witness_not_directory_inventory','nativeAcceptance':'not_run','fullBERAcceptance':False,'rubricRescored':False}

def main(argv=None):
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--repo-root',required=True);p.add_argument('--fault-ref',required=True);p.add_argument('--actor-ref',required=True);p.add_argument('--output',required=True);a=p.parse_args(argv);repo=Path(a.repo_root).resolve()
 try:result=verify_s4_preparation_fault(exact_ref(bounded_json(a.fault_ref)),exact_ref(bounded_json(a.actor_ref)),repo);ref=immutable_report(a.output,result,repo);print(json.dumps({'status':'verified_subset','report':ref,'fullBERAcceptance':False}));return 0
 except (AssertionError,KeyError,TypeError,ValueError,OSError) as e:print(json.dumps({'status':'blocked','code':'BER_S4_PREPARATION_FAULT_EVIDENCE_UNVERIFIABLE','errorClass':type(e).__name__}));return 2
if __name__=='__main__':raise SystemExit(main())
